import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    output_lines = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            k = int(next(iterator))
        except StopIteration:
            break

        A = []
        for _ in range(N):
            A.append(int(next(iterator)))

        count = 0
        for i in range(N):
            val_i = A[i]
            target = val_i + k
            for j in range(i + 1, N):
                val_j = A[j]
                left = (val_i | val_j) + (val_i ^ val_j) + (val_i & val_j)
                right = k + val_j
                if left == right:
                    count += 1

        output_lines.append(str(count))

    sys.stdout.write('\n'.join(output_lines) + '\n')

if __name__ == '__main__':
    solve()
